#!/usr/bin/env python3
"""Build an offline, trilingual R2a demo guide from explicit facts and original screenshots."""
import base64
import hashlib
import html
import json
import re
import subprocess
from pathlib import Path

HERE = Path(__file__).resolve().parent
OUT = HERE.parent.parent / 'mekoniq-r2a-demo-guide.html'
FACTS = json.loads((HERE / 'facts.json').read_text())
E = html.escape
COMMANDS = []
TRANSLATIONS = []

def tr(vi, ja, en):
    assert all(isinstance(s, str) and s.strip() for s in (vi, ja, en))
    TRANSLATIONS.append([vi, ja, en])
    return ''.join(f'<span class="i18n" lang="{lang}">{E(text)}</span>' for lang, text in zip(('vi', 'ja', 'en'), (vi, ja, en)))

def p(vi, ja, en, cls=''):
    return f'<p class="{cls}">{tr(vi, ja, en)}</p>'

def title(number, vi, ja, en, desc):
    return f'<div class="section-heading"><span class="section-no">{number}</span><div><h2>{tr(vi, ja, en)}</h2>{p(*desc)}</div></div>'

def command(id_, text, shell=True):
    if shell:
        subprocess.run(['bash', '-n'], input=text, text=True, check=True, capture_output=True)
        COMMANDS.append(text)
    return f'<div class="code"><div class="code-top"><span>{"TERMINAL" if shell else "URL"}</span><button type="button" class="copy interactive" data-copy="{id_}">{tr("Sao chép", "コピー", "Copy")}</button></div><pre id="{id_}"><code>{E(text)}</code></pre></div>'

def step(n, heading, body, result=None):
    return f'<li class="step"><span class="step-no">{n:02}</span><div><h3>{tr(*heading)}</h3>{p(*body)}'+(f'<p class="expected"><b>{tr("Mong đợi", "確認する結果", "Expected")}</b> {tr(*result)}</p>' if result else '')+'</div></li>'

def image(id_, caption, hero=False):
    meta = next(i for i in FACTS['images'] if i['id'] == id_)
    raw = (HERE / meta['file']).read_bytes()
    assert hashlib.sha256(raw).hexdigest() == meta['sha256'], 'Screenshot changed: '+id_
    uri = 'data:image/png;base64,'+base64.b64encode(raw).decode()
    alts = ' '.join(f'data-alt-{lang}="{E(text, quote=True)}"' for lang, text in zip(('vi','ja','en'),caption))
    return f'<figure class="shot {"hero-shot" if hero else ""}"><button type="button" data-zoom="{id_}" class="image-button" aria-label="{E(caption[0], quote=True)}" {alts}><img src="{uri}" width="{meta["width"]}" height="{meta["height"]}" alt="{E(caption[0], quote=True)}" {alts} loading="{"eager" if hero else "lazy"}"></button><figcaption>{tr(*caption)} <span class="shot-scope">{tr("Ảnh kiểm thử tự động · local", "自動テストの画像 · ローカル", "Automated test capture · local")}</span></figcaption></figure>'

def feature(num, name, desc, tag):
    return f'<article class="feature"><div class="feature-top"><span>{num}</span><small>{E(tag)}</small></div><h3>{tr(*name)}</h3>{p(*desc)}</article>'

def details(heading, body):
    return f'<details><summary>{tr(*heading)}</summary><div class="details-body">{body}</div></details>'

assert FACTS['schemaVersion'] == 1 and FACTS['humanAcceptance'] is False
assert re.fullmatch('[a-f0-9]{40}', FACTS['runtimeSourceCommit'])
assert FACTS['cloud']['httpSmoke'] == 'tested' and FACTS['cloud']['browserSmoke'] == 'passed'
assert FACTS['manualBrowserChecks']['status'] == 'not_run'
assert FACTS['productionLabStatus'] == 'READY' and FACTS['productionSourceStatus'] == 'READY'
CLOUD = FACTS['cloud']['url']
LOCAL = 'http://127.0.0.1:4175/#twin'

nav = [('overview','Tổng quan','概要','Overview'),('connect','Chọn Web / Local','Web / ローカル','Web / Local'),('demo','Demo tay máy','アームのデモ','Arm demo'),('features','Chức năng','機能','Features'),('capabilities','Backend & môi trường','Backendと環境','Backends & environments'),('proof','Bằng chứng','証跡','Evidence'),('help','Xử lý nhanh','トラブル対処','Troubleshooting')]
sidebar = '<aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark" aria-hidden="true">M</span><span>MEKONIQ<small>ROBOT LAB</small></span></a><div class="edition">R2a <span>DEMO GUIDE</span></div><nav>'+''.join(f'<a href="#{id_}"><span>{i:02}</span>{tr(vi,ja,en)}</a>' for i,(id_,vi,ja,en) in enumerate(nav))+'</nav><div class="sidebar-note">'+p('Từ giao diện đến một lần chạy có bằng chứng.','画面から証跡付きの実行まで。','From the interface to an evidenced run.')+'<span class="mono">14 NOV 2026</span></div></aside>'
toolbar = '<div class="toolbar"><a class="mobile-brand" href="#overview">MEKONIQ <span>R2a</span></a><div class="toolbar-right"><div class="language interactive" role="group" aria-label="Language">'+''.join(f'<button type="button" data-lang-switch="{lang}" aria-pressed="{str(lang=="vi").lower()}">{label}</button>' for lang,label in [('vi','VI'),('ja','日本語'),('en','EN')])+'</div><button class="print interactive" type="button" data-print>'+tr('In / PDF','印刷 / PDF','Print / PDF')+'</button></div></div>'
hero = '<section id="overview" class="hero"><div class="hero-copy"><p class="eyebrow">R2a / '+tr('HƯỚNG DẪN DEMO','デモガイド','DEMO GUIDE')+'</p><h1>'+tr('Một tay máy.\nHai cách demo.','ひとつのアーム。\nふたつのデモ。','One arm.\nTwo ways to demo.')+'</h1>'+p('Khám phá xArm 6 trong MuJoCo, theo dõi từng khớp và phát lại một lần gắp cốc — trên runtime cloud hoặc máy của bạn.','MuJoCo内のxArm 6を動かし、各関節を確認し、カップ把持を再生。クラウドまたは自分のマシンで実行します。','Explore the xArm 6 in MuJoCo, inspect its joints and replay a cup transfer — using a cloud runtime or your own machine.','hero-lead')+'<div class="hero-actions"><a class="button lime" href="#connect" data-route-link="local">'+tr('Bắt đầu tại máy này','ローカルで始める','Start locally')+' <span aria-hidden="true">↗</span></a><a class="button outline" href="#connect" data-route-link="web">'+tr('Xem cách demo Web','Webデモを見る','Explore the web route')+'</a></div><div class="hero-metrics"><div><b>xArm 6 + G2</b><span>'+tr('Mô hình được mô phỏng','シミュレーションするモデル','Model being simulated')+'</span></div><div><b>4,800</b><span>'+tr('tick · CL01 qua HTTP','tick · HTTP CL01','ticks · HTTP CL01')+'</span></div><div><b>2</b><span>'+tr('lượt phục vụ hoàn tất','完了した提供数','completed servings')+'</span></div></div></div>'+image('arm',('MuJoCo: cốc được gắp bằng tiếp xúc mô phỏng.','MuJoCo: 模擬接触によるカップ把持。','MuJoCo: a cup held by simulated contact.'),True)+'</section>'
state = '<div class="status-strip"><span class="status good">'+tr('Cloud Run · HTTP đã đạt','Cloud Run · HTTP検証済み','Cloud Run · HTTP tested')+'</span><span class="status good">'+tr('Lab production · READY','本番Lab · READY','Production Lab · READY')+'</span><span class="status neutral">'+tr('Chưa nghiệm thu bởi con người','人による承認は未実施','Human acceptance pending')+'</span></div>'+p('Snapshot 14/11/2026. Hai nhánh main đã push; source và Lab đã READY trên production. Runtime cloud chạy cùng pin 4f893ac; demo Chrome production đã đạt. Ảnh minh họa vẫn là bản ghi kiểm UI local.','2026年11月14日の状態。両mainをpush済みで、sourceとLabの本番はREADYです。cloud runtimeは固定版4f893acを実行し、本番Chromeデモも成功。説明用画像はローカルUIテストの記録です。','Snapshot: 14 November 2026. Both main branches were pushed; source and Lab are READY in production. Cloud runs the same 4f893ac pin; the production Chrome demo passed. Illustrations remain local UI test captures.','snapshot')

web = '<section id="route-web" data-route-panel="web" aria-labelledby="tab-web"><div class="route-heading"><div><span class="eyebrow">WEB / CLOUD RUN</span><h3>'+tr('Demo không cần engine trên máy khách','クライアントにエンジン不要','No engine on the client machine')+'</h3></div><span class="status good">'+tr('Lab production · READY','本番Lab · READY','Production Lab · READY')+'</span></div>'+p('Dùng giao diện Lab qua HTTPS và runtime MuJoCo đã deploy tại Singapore. Trước buổi demo, build Lab phải ghim source 4f893ac; bản khác sẽ bị chặn bằng RUNTIME_PIN_MISMATCH.','HTTPSのLab画面と、シンガポールに公開済みのMuJoCoランタイムを使います。デモ前にLabがsource 4f893acを固定している必要があります。異なる版はRUNTIME_PIN_MISMATCHで拒否されます。','Use the HTTPS Lab interface and the MuJoCo runtime deployed in Singapore. Before the demo, the Lab build must pin source 4f893ac; another version is blocked with RUNTIME_PIN_MISMATCH.','route-lead')+'<ol class="steps">'+step(1,('Mở đúng build Lab','対応するLabビルドを開く','Open the matching Lab build'),('Mở mekoniq-lab.vercel.app và chọn “Bản sao số”. Bản production a744954 đã READY. Trang web chỉ là giao diện; runtime nằm ở URL bên dưới.','mekoniq-lab.vercel.appで「デジタルツイン」を開きます。本番a744954はREADYです。WebページはUIで、ランタイムは下記URLにあります。','Open mekoniq-lab.vercel.app and select Digital twin. Production build a744954 is READY. The web page is the UI; the runtime lives at the URL below.'))+step(2,('Chọn “Địa chỉ khác”','「別のアドレス」を選択','Choose “Another address”'),('Mở chip Runtime trên thanh trên cùng. Chọn “Địa chỉ khác”, rồi dán nguyên URL chuẩn — không dùng URL Cloud Run có số project.','上部のRuntimeチップを開き、「別のアドレス」を選んで正規URLを貼り付けます。プロジェクト番号入りの別URLは使いません。','Open the Runtime chip, choose Another address and paste the exact canonical URL. Do not substitute the Cloud Run alias containing the project number.'))+'</ol>'+command('cloud-url',CLOUD,False)+'<ol class="steps" start="3">'+step(3,('Ghép nối bằng khóa truy cập','アクセスキーでペアリング','Pair with the access key'),('Nhập khóa do người vận hành cấp vào ô mã ghép nối, rồi bấm “Ghép nối runtime”. Cloud dùng khóa chung; mã local một lần không dùng ở đây. HTML này không chứa hoặc đọc khóa.','運用担当者から受け取ったキーをペアリング欄に入力し、ペアリングします。クラウドでは共通アクセスキーを使用し、ローカルのワンタイムコードは使いません。このHTMLはキーを含まず読み取りもしません。','Enter the operator-provided access key in the pairing field and click Pair runtime. Cloud uses a shared access key; a local one-time code will not work here. This HTML never contains or reads the key.'),('“Lab ghim” và “Runtime chạy” cùng 4f893ac; trạng thái sẵn sàng.','「Labの固定」と「ランタイムの版」がともに4f893acで、準備完了になる。','Lab pinned to and Runtime runs both show 4f893ac; the connection is ready.'))+'</ol><div class="route-links"><a class="button dark" href="'+FACTS['productionLabUrl']+'/#twin" target="_blank" rel="noopener">'+tr('Mở Lab production ↗','本番Labを開く ↗','Open production Lab ↗')+'</a><a href="'+CLOUD+'/lab/v2/health" target="_blank" rel="noopener">'+tr('Xem health công khai ↗','公開healthを見る ↗','View public health ↗')+'</a></div>'+p('Cloud runtime này có mock và mujoco_arm. IR-SIM, Webots và LinkForge cần môi trường local. Origin web được phép là https://mekoniq-lab.vercel.app; một trang localhost không tự được quyền gọi runtime cloud này.','このクラウドランタイムにはmockとmujoco_armがあります。IR-SIM、Webots、LinkForgeはローカル環境が必要です。許可されたWebオリジンはhttps://mekoniq-lab.vercel.appで、localhostのページは自動では許可されません。','This cloud runtime includes mock and mujoco_arm. IR-SIM, Webots and LinkForge require the local environment. The allowed web origin is https://mekoniq-lab.vercel.app; a localhost page is not automatically allowed to call this cloud runtime.','note')+'</section>'

local = '<section id="route-local" data-route-panel="local" aria-labelledby="tab-local"><div class="route-heading"><div><span class="eyebrow">LOCAL / MAC · LINUX</span><h3>'+tr('Demo ngay trên máy đã chuẩn bị','準備済みのマシンでデモ','Demo on a prepared machine')+'</h3></div><span class="status good">'+tr('UI đã kiểm tự động','UI自動テスト済み','UI automatically tested')+'</span></div>'+p('UI và runtime cùng chạy loopback. Cần Node 24.22.2, pnpm 10.32.1, runtime đã nhập đúng pin, source ở cạnh lab và .venv-mujoco đã cài theo lock. Launcher không tự tải engine hoặc đổi pin.','UIとランタイムを同じマシンのループバックで動かします。Node 24.22.2、pnpm 10.32.1、固定版のランタイム、labと隣接するsource、lockどおりの.venv-mujocoが必要です。ランチャーはエンジンのダウンロードや固定版の変更を行いません。','UI and runtime both run on loopback. You need Node 24.22.2, pnpm 10.32.1, the imported pinned runtime, source beside lab, and .venv-mujoco installed from its lock. The launcher does not download an engine or change the pin.','route-lead')+p('Từ thư mục workspace robot trên máy hiện tại:','現在のマシンのrobotワークスペースから:','From the robot workspace on the current machine:')+command('launch-mujoco','export PATH="$HOME/.nvm/versions/node/v24.22.2/bin:$PATH"\ncd lab\npnpm check:source\npnpm lab:mujoco')+'<ol class="steps">'+step(1,('Giữ terminal chạy','ターミナルを起動したままにする','Leave the terminal running'),('Launcher mở UI 4175 và runtime 4176, rồi in mã ghép nối một lần. Chỉ chạy một launcher dùng các cổng này; Ctrl+C trong terminal đó để dừng sau demo.','ランチャーがUIの4175とランタイムの4176を開き、ワンタイムコードを表示します。同じポートではランチャーを1つだけ実行し、デモ後はそのターミナルでCtrl+Cを押します。','The launcher opens UI 4175 and runtime 4176, then prints a one-time pairing code. Run only one launcher on these ports; use Ctrl+C in that terminal to stop it after the demo.'))+step(2,('Mở Lab local và ghép nối','ローカルLabを開いてペアリング','Open local Lab and pair'),('Mở URL bên dưới, chọn “Máy này” trong hộp Runtime, rồi nhập mã vừa in. UI do launcher phục vụ dùng runtime cùng origin; không cần dán URL cloud.','下記URLを開き、Runtimeで「このマシン」を選択して表示されたコードを入力します。ランチャーのUIは同一オリジンのランタイムを使うため、クラウドURLは不要です。','Open the URL below, choose This machine in the Runtime box and enter the printed code. The launcher-served UI uses its same-origin runtime; no cloud URL is needed.'),('Runtime sẵn sàng; kịch bản MuJoCo có thể chọn.','Runtimeが準備完了となり、MuJoCoシナリオを選択できる。','The runtime is ready and the MuJoCo scenario can be selected.'))+'</ol>'+command('local-url',LOCAL,False)+details(('Chỉ muốn xem thiết kế hoặc demo mock?','設計の閲覧やmockだけ試したい場合','Only need design preview or a mock demo?'),p('Trong thư mục lab, chọn một lệnh. pnpm dev chỉ mở UI để thiết kế; pnpm lab:mock mở cả UI và runtime mock. Dừng launcher đang dùng trước khi đổi.','labディレクトリでいずれかのコマンドを選びます。pnpm devは設計用UIだけ、pnpm lab:mockはUIとmockランタイムを起動します。切り替え前に既存のランチャーを停止してください。','In lab, choose one command. pnpm dev opens design UI only; pnpm lab:mock starts both UI and the mock runtime. Stop the current launcher before switching.')+command('launch-preview','pnpm dev')+command('launch-mock','pnpm lab:mock'))+details(('Chuẩn bị MuJoCo trên máy mới','新しいマシンでMuJoCoを準備','Prepare MuJoCo on a new machine'),p('Cần Python 3.11. Từ source, bootstrap công cụ theo lock; sau đó nhận/import runtime export đúng source mà Lab đang ghim. Nếu RUNTIME_NOT_INSTALLED hoặc PORTABLE_TOOLS_MISMATCH, xử lý gói runtime trước, không sửa lock chỉ để vượt kiểm tra.','Python 3.11が必要です。sourceからlockに従ってツールを準備し、Labの固定版と同じsourceからexportしたランタイムを受け取り/importします。RUNTIME_NOT_INSTALLEDやPORTABLE_TOOLS_MISMATCHの場合、チェック回避のためにlockを書き換えず、ランタイムの配布物を修正します。','Python 3.11 is required. From source, bootstrap the tool from its lock, then obtain/import a runtime export matching the source commit pinned by Lab. Resolve RUNTIME_NOT_INSTALLED or PORTABLE_TOOLS_MISMATCH through the runtime package; do not edit the lock to bypass the check.')+command('bootstrap-mujoco','cd source\nnode scripts/bootstrap-portable-simulation.mjs mujoco'))+p('Dùng http://127.0.0.1:4175 cho đường local trực tiếp. Kết nối từ một trang HTTPS đến loopback còn phụ thuộc allowlist origin và quyền trình duyệt; kiểm tay Chrome/Firefox/Safari cho luồng đó chưa chạy.','直接ローカルで使う場合はhttp://127.0.0.1:4175を開きます。HTTPSページからloopbackへの接続はオリジン許可とブラウザ権限に依存し、Chrome/Firefox/Safariでの手動確認は未実施です。','Use http://127.0.0.1:4175 for the direct local route. HTTPS-page-to-loopback access also depends on origin allowance and browser permissions; manual Chrome/Firefox/Safari checks of that route have not run.','note')+'</section>'

connect = '<section id="connect" class="section">'+title('01','Chọn nơi chạy runtime','ランタイムの実行場所を選ぶ','Choose where the runtime runs',('Hai đường dẫn đến cùng giao diện Bản sao số. Chọn Local để demo ngay trong môi trường đã chuẩn bị.','同じデジタルツインUIに至る2つの経路。準備済み環境ではローカルで開始できます。','Two routes to the same Digital twin interface. Choose Local to start in the prepared environment.'))+'<div class="route-tabs interactive" role="tablist" aria-label="Demo route"><button type="button" id="tab-local" role="tab" data-route="local" aria-controls="route-local" aria-selected="true">'+tr('Local · máy này','ローカル · このマシン','Local · this machine')+'</button><button type="button" id="tab-web" role="tab" data-route="web" aria-controls="route-web" aria-selected="false" tabindex="-1">'+tr('Web · Cloud Run','Web · Cloud Run','Web · Cloud Run')+'</button></div><div class="route-card">'+local+web+'</div></section>'

demoSteps = [
 (('Chọn đúng kịch bản','正しいシナリオを選択','Choose the scenario'),('Trong “Bản sao số”, mở “Kịch bản” trên thanh đầu. Chọn “MuJoCo · cà phê với tay máy xArm 6”, rồi bấm “Chạy MuJoCo (tay máy)”.','「デジタルツイン」の上部「シナリオ」から「MuJoCo · xArm 6でコーヒー」を選び、「MuJoCo実行(アーム)」を押します。','In Digital twin, open the Scenario picker. Choose “MuJoCo · coffee with xArm 6”, then “Run MuJoCo (arm)”.'),('Nhãn “Mô phỏng · chưa hiệu chuẩn”; source 4f893ac; cảnh mở ở trạm tay máy.','「シミュレーション · 未校正」、source 4f893ac、アームセルが表示される。','The label says Simulation · not calibrated, source is 4f893ac, and the view frames the arm cell.')),
 (('Cho chạy 1× và quan sát','1×で実行して観察','Run at 1× and observe'),('Chọn 1× rồi bấm “Tự chạy”. Quan sát kẹp đóng, cốc được nâng và chuyển đến khay. Xoay camera, dùng Home để về trạm; Fit khi không chọn đối tượng để thấy cả mặt bằng.','1×を選び「自動実行」。グリッパーが閉じ、カップを持ち上げトレーへ移す様子を見ます。カメラを回し、Homeでセルへ戻り、未選択のFitで床全体を表示します。','Select 1× and click Auto-run. Watch the gripper close, lift a cup and transfer it to the tray. Orbit the camera, use Home to frame the cell, or Fit with nothing selected to show the floor.'),('Camera bạn chọn được giữ khi tick mới đến; khối lượng/giới hạn danh định, tiếp xúc và bố trí vẫn giả định.','tick更新後もカメラ視点を保持。質量と制限は公称値、接触と配置は仮定のまま。','Your camera stays in place as ticks arrive. Masses and limits are nominal; contact and cell layout are still assumed.')),
 (('Giải thích dữ liệu đang thấy','表示データを説明','Explain the observed data'),('Mở “Chi tiết” → “Đối tượng”, chọn “Cánh tay 1”; qua “Kỹ thuật” để so khớp quan sát từ MuJoCo với khớp lệnh. Tạm dừng mô phỏng khi cần nói; tiếp tục và bật Tự chạy lại nếu cần.','「詳細」→「対象」でアーム1を選び、「エンジニアリング」でMuJoCo観測関節と指令関節を比較します。説明中はシミュレーションを一時停止し、再開後は必要に応じて自動実行を再度オンにします。','Open Details → Objects, select Arm 1, then use Engineering to compare MuJoCo-observed joints with commanded joints. Pause simulation while explaining; resume and re-enable Auto-run if needed.'),('Hai cột giá trị có đơn vị và nguồn. Chế độ xem ẩn phần giao diện phụ, vẫn có nút thoát để chạm.','2列に単位と出典を表示。視聴モードは補助UIを隠し、タッチで終了できる。','Both columns show values, units and source. Watch mode hides secondary UI and keeps a touch-accessible exit.')),
 (('Tăng tốc để hoàn tất','加速して完了まで進める','Speed up to completion'),('Chọn 16× để đi đến cuối bài demo. Các mức 1×/4×/16×/64× là mục tiêu nhịp; nếu máy hoặc mạng chậm, đọc tốc độ đo được thay vì hứa đạt hệ số đã chọn.','16×でデモの終わりまで進めます。1×/4×/16×/64×は目標ペースです。マシンやネットワークが遅い場合、選択倍率を保証せず実測速度を読みます。','Choose 16× to reach the end. The 1×/4×/16×/64× choices are pacing targets; when the machine or network is slow, use the measured speed instead of promising the selected factor.'),('“Hoàn thành”, “Đã giao 2”. Đọc tick cuối trong báo cáo: bài kiểm UI ghi 4810, còn CL01 qua HTTP ghi 4800 do chia bước khác nhau.','「完了」「提供数2」を確認し、最終tickをレポートで読みます。UIテストは4810、HTTP CL01は4800。ステップ単位の違いによるものです。','Look for Completed and Served 2, then read the final tick in the report. The UI baseline records 4810; HTTP CL01 records 4800 because it uses different step batches.')),
 (('Giữ bằng chứng và phát lại','証跡を保存して再生','Keep evidence and replay'),('Trong “Chi tiết” → “Báo cáo”, xem engine mujoco_3d, grip contact, not_calibrated và kiểm va chạm. Xuất JSON/CSV/HTML hoặc “Lưu báo cáo bất biến”. Chọn “Xem lại (chỉ đọc)” rồi kéo thanh tick về lúc gắp cốc.','「詳細」→「レポート」でmujoco_3d、contact把持、not_calibrated、衝突チェックを確認します。JSON/CSV/HTML出力または不変レポート保存後、「再生(読み取り専用)」で把持時点に戻します。','In Details → Report, inspect mujoco_3d, contact grip, not_calibrated and collision checks. Export JSON/CSV/HTML or Save immutable report. Select Replay (read only) and scrub back to the cup transfer.'),('Chip “Bản ghi”; tay máy và cốc theo mẫu đã lưu. Replay không chạy lại engine hoặc gửi lệnh robot.','「記録」チップが表示され、アームとカップは保存サンプルに従う。再生はエンジン再実行やロボット指令を行わない。','The chip says Recorded; arm and cup follow saved samples. Replay does not rerun the engine or send robot commands.')),
]
demo = '<section id="demo" class="section">'+title('02','Một kịch bản demo trọn vẹn','ひととおりのデモ手順','One complete demo sequence',('Chuẩn bị 5–8 phút cho phần giới thiệu, thao tác và giải thích kết quả. Đây là thời lượng trình bày gợi ý, không phải cam kết hiệu năng.','紹介、操作、結果説明に5〜8分を用意。これはプレゼンの目安であり、性能保証ではありません。','Allow 5–8 minutes to introduce, operate and explain the result. This is a presentation suggestion, not a performance guarantee.'))+'<ol class="steps demo-steps">'+''.join(step(i,h,b,r) for i,(h,b,r) in enumerate(demoSteps,1))+'</ol><div class="checklist"><h3>'+tr('Trước khi bắt đầu trình bày','発表を始める前に','Before presenting')+'</h3><div class="checks">'+''.join('<label><input type="checkbox" class="prep-check">'+tr(*c)+'</label>' for c in [('Đúng pin ở cả Lab và runtime','Labとruntimeの固定版が一致','Lab and runtime pins match'),('Có mã/khóa ghép nối hợp lệ','有効なコード/キーを用意','Valid pairing code/key is available'),('Chọn được preset MuJoCo','MuJoCoプリセットを選択可能','MuJoCo preset can be selected'),('Giải thích rõ phạm vi mô phỏng','シミュレーションの範囲を説明','Explain the simulation scope')])+'</div><div class="prep-footer"><output id="prep-count">0 / 4</output><span>'+tr('mục chuẩn bị đã đánh dấu · không phải kết quả kiểm thử','準備項目にチェック · テスト結果ではない','preparation items checked · not test results')+'</span><button type="button" class="interactive" data-reset-checks>'+tr('Bỏ đánh dấu','クリア','Clear')+'</button></div></div></section>'

demo = demo.replace('</ol><div class="checklist">', '</ol><div class="notice">'+p('Trước lượt MuJoCo tiếp theo: thoát replay, rồi bấm “Chạy lại cùng đầu vào” trong cùng tab. Lab lưu bằng chứng và archive lượt cũ trước khi tạo lượt mới. Cloud có một chỗ chạy MuJoCo; chỉ ngắt kết nối không giải phóng chỗ đó. Với local, dùng Ctrl+C trong terminal launcher khi kết thúc demo.','次のMuJoCoデモ前に再生を終了し、同じタブで「同じ入力で再実行」を押します。Labは証跡を保存し旧runをarchiveしてから次を作成します。cloudのMuJoCo枠は1つで、切断だけでは解放されません。ローカルのデモ終了時はランチャーのターミナルでCtrl+Cを押します。','Before the next MuJoCo demo, exit replay and use Run again with same inputs in the same tab. Lab saves evidence and archives the previous run before creating the next one. Cloud has one MuJoCo worker slot; disconnecting alone does not free it. For local demos, finish with Ctrl+C in the launcher terminal.')+'</div><div class="checklist">')

features = '<section id="features" class="section">'+title('03','Những chức năng nên cho xem','紹介したい機能','Features worth showing',('Thiết kế, quan sát và kiểm kết quả là ba việc khác nhau. Chỉ runtime thực thi mới tạo kết quả chạy.','設計、観察、結果の確認は別の作業です。実行結果はランタイムが生成します。','Designing, observing and checking results are distinct. Only an executing runtime produces a run result.'))+'<div class="features">'+''.join([
feature('01',('Thiết kế không cần runtime','ランタイム不要の設計','Design without a runtime'),('Khám phá cấu hình robot, bố trí và bản xem trước. Các thay đổi thiết kế không tự thay thế fixture xArm của bài mô phỏng.','ロボット構成、配置、プレビューを探索。設計変更がxArmシミュレーションのfixtureを自動置換することはありません。','Explore robot configuration, layout and preview. Design changes do not automatically replace the xArm simulation fixture.'),'DESIGN'),
feature('02',('Tay máy từ mesh thực','実モデルのメッシュ表示','Arm from actual model meshes'),('xArm 6 và kẹp G2 hiển thị từ mesh; cốc theo pose plant. Nếu mesh thiếu, hình thay thế và lưu ý vẫn hiện.','xArm 6とG2をメッシュで表示し、カップはプラントposeに従う。メッシュ欠落時は代替形状と注意を表示。','xArm 6 and G2 use meshes; cups follow plant poses. Missing meshes produce fallback geometry with a visible note.'),'MUJOCO'),
feature('03',('Nhịp và điều khiển gọn','ペースとコンパクトな操作','Pacing and compact controls'),('Tự chạy, +5 s, tạm dừng/tiếp tục, tốc độ và hủy lần chạy. Thanh trạng thái giữ nhãn mô phỏng ở mọi chế độ.','自動実行、+5秒、一時停止/再開、速度、キャンセル。状態バーは常にシミュレーション表示を保持。','Auto-run, +5 s, pause/resume, speed and cancel. The status bar keeps the simulation label visible.'),'1× / 4× / 16× / 64×'),
feature('04',('Không gian quan sát','観察するための画面','A workspace for observation'),('Đổi 2D/3D, orbit, Home/Fit, mở Chi tiết khi cần. Chế độ xem có nút thoát trên cả màn hình cảm ứng.','2D/3D、orbit、Home/Fit、必要なときだけ詳細を表示。視聴モードはタッチでも終了できる。','Switch 2D/3D, orbit, use Home/Fit and open Details when needed. Watch mode can be exited on touch screens.'),'VIEWPORT'),
feature('05',('Lệnh so với quan sát','指令と観測を比較','Commanded versus observed'),('Đọc vị trí khớp, đơn vị, nguồn và tuổi dữ liệu. Không nhầm giá trị lệnh với số đo từ plant.','関節値、単位、出典、データ経過時間を確認。指令値とプラント観測を区別。','Read joint positions, units, source and age. Distinguish commanded values from plant observations.'),'TELEMETRY'),
feature('06',('Báo cáo và replay','レポートと再生','Reports and replay'),('Xuất JSON/CSV/HTML, lưu báo cáo bất biến và kéo thanh tick. Replay dùng dữ liệu đã ghi, không tạo run mới.','JSON/CSV/HTML出力、不変レポート保存、tick移動。再生は記録データを使い新規実行を作らない。','Export JSON/CSV/HTML, save an immutable report and scrub ticks. Replay uses recorded data without creating a new run.'),'EVIDENCE')])+'</div><div class="gallery">'+image('joints',('Kỹ thuật: so sánh khớp quan sát và lệnh.','エンジニアリング: 観測関節と指令を比較。','Engineering: compare observed and commanded joints.'))+image('replay',('Replay: quay lại thời điểm cốc đang được chuyển.','再生: カップ搬送中の時点に戻る。','Replay: return to the middle of a cup transfer.'))+image('watch',('Chế độ xem và nút thoát cảm ứng — ảnh từ kịch bản mock.','視聴モードとタッチ用終了ボタン — mockシナリオの画像。','Watch mode and its touch exit — captured in a mock scenario.'))+'</div></section>'

rows=[
 (('Xem thiết kế / bản xem trước','設計 / プレビュー','Design / preview'),('Có UI; không cần runtime','UIのみで利用可能','UI only; no runtime needed'),('pnpm dev','pnpm dev','pnpm dev')),
 (('Mock phục vụ và cà phê','配膳・コーヒーのmock','Serving and coffee mocks'),('Có trong image','イメージに含まれる','Included in the image'),('pnpm lab:mock','pnpm lab:mock','pnpm lab:mock')),
 (('MuJoCo xArm 6 · MJ-BV01','MuJoCo xArm 6 · MJ-BV01','MuJoCo xArm 6 · MJ-BV01'),('Có · HTTP CL01 đã đạt','対応 · HTTP CL01検証済み','Available · HTTP CL01 tested'),('pnpm lab:mujoco','pnpm lab:mujoco','pnpm lab:mujoco')),
 (('IR-SIM 2D + LinkForge shadow','IR-SIM 2D + LinkForge shadow','IR-SIM 2D + LinkForge shadow'),('Không đóng gói','含まれない','Not packaged'),('pnpm lab:irsim + venv theo lock','pnpm lab:irsim + lock準拠venv','pnpm lab:irsim + locked venvs')),
 (('Webots 3D / tay máy Webots','Webots 3D / Webotsアーム','Webots 3D / Webots arm'),('Không đóng gói','含まれない','Not packaged'),('pnpm lab:webots + Webots R2025a','pnpm lab:webots + Webots R2025a','pnpm lab:webots + Webots R2025a')),
 (('Robot thật / LinuxCNC / Gazebo','実機 / LinuxCNC / Gazebo','Real robot / LinuxCNC / Gazebo'),('Ngoài demo R2a này','このR2aデモの範囲外','Outside this R2a demo'),('Không suy ra từ bài mô phỏng','このシミュレーションから推定しない','Not established by this simulation')),
]
capabilities='<section class="section" id="capabilities">'+title('04','Chạy được ở đâu?','どこで実行できるか','What runs where?',('Ma trận này mô tả image cloud đã deploy và các launcher hiện có, không hứa mọi backend có trên một runtime.','この表は公開済みクラウドイメージと既存ランチャーの範囲です。1つのruntimeで全backendを提供するものではありません。','This matrix describes the deployed cloud image and available launchers; a single runtime does not expose every backend.'))+'<div class="table-wrap"><table><thead><tr><th>'+tr('Chức năng','機能','Capability')+'</th><th>Web / Cloud Run</th><th>Local</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+tr(*cell)+'</td>' for cell in row)+'</tr>' for row in rows)+'</tbody></table></div>'+p('Đổi launcher sau khi dừng launcher cũ. Không dùng các cổng robot vận hành 1880/1884 cho buổi demo.','既存ランチャーを停止してから切り替えます。デモで稼働中ロボットの1880/1884ポートを使わないでください。','Stop the previous launcher before switching. Do not use the operational robot ports 1880/1884 for this demo.','note')+'</section>'

proof='<section id="proof" class="section">'+title('05','Điều đã được chứng minh','確認できたこと','What the evidence establishes',('Kết quả kiểm phần mềm, nghiệm thu và giới hạn mô hình được ghi riêng.','ソフトウェア検証、承認、モデルの限界を区別します。','Software verification is kept distinct from acceptance and the limits of the model.'))+'<div class="proof-grid"><article class="proof-card"><span class="status good">'+tr('Đã chạy','実行済み','Executed')+'</span><h3>Cloud Run · CL01</h3>'+p('Health, ghép nối khóa sai/đúng, mock FD01, SSE nối lại và MJ-BV01 đều đạt trên Linux x86-64 thật. MJ-BV01 kết thúc ở tick 4800, phục vụ 2; vòng bước HTTP khoảng 71,3 giây, gồm mạng và xử lý; không phải số đo CPU mỗi tick. Cả hai run của bài kiểm đã được archive.','health、誤/正キーのペアリング、mock FD01、SSE再接続、MJ-BV01がLinux x86-64実機上で成功。MJ-BV01はtick 4800・提供2で終了。HTTPステップ全体はネットワーク込みで約71.3秒。CPU/tickの指標ではありません。テストの2つのrunはarchive済みです。','Health, wrong/right-key pairing, mock FD01, SSE reconnection and MJ-BV01 passed on native Linux x86-64. MJ-BV01 finished at tick 4800, served 2; HTTP stepping took about 71.3 seconds including network and processing, not a CPU-per-tick benchmark. Both runs created by the check were archived.')+'</article><article class="proof-card"><span class="status good">'+tr('Đã kiểm tự động','自動検証済み','Automatically tested')+'</span><h3>'+tr('Lab local + hồi quy','ローカルLab + 回帰','Local Lab + regression')+'</h3>'+p('Các bản ghi IR-SIM, R1, R1.1, R2a và R-MOCK mới dùng cùng pin. UI đã kiểm mesh, điều khiển, kết nối, watch mode, báo cáo và replay; ảnh trong tài liệu lấy từ các bài này.','IR-SIM、R1、R1.1、R2a、R-MOCKの新しい記録は同じ固定版を使用。UIはmesh、操作、接続、視聴モード、レポート、再生を検証し、この資料の画像もそのテストから取得。','The new IR-SIM, R1, R1.1, R2a and R-MOCK records share the same pin. UI checks cover meshes, controls, connection, watch mode, reports and replay; this guide’s images come from those tests.')+'</article><article class="proof-card"><span class="status good">'+tr('Chrome tự động · đã đạt','Chrome自動テスト済み','Automated Chrome · passed')+'</span><h3>'+tr('Production UI & trình duyệt','本番UIとブラウザ','Production UI & browsers')+'</h3>'+p('Source d1a2522 và Lab a744954 đã READY trên Vercel; /health/live và /health/ready trả HTTP 200 với true. Chrome 157 headless từ origin production đã ghép nối và hoàn thành MJ-BV01: tick 4810, phục vụ 2, đã archive run. Ở mức chọn 16×, lượt UI mất 78,4 giây gồm mạng, UI và đọc báo cáo; không phải đo CPU hay nhịp 1×. Kiểm tay Chrome/Firefox/Safari cho HTTPS → loopback và nghiệm thu bởi con người chưa thực hiện.','source d1a2522とLab a744954はVercelでREADY。/health/liveと/health/readyはHTTP 200、trueです。本番originのheadless Chrome 157でペアリングとMJ-BV01が成功し、tick 4810・提供2で終了、runはarchive済み。選択16×のUI実行はネットワーク・UI・レポート取得込みで78.4秒。CPUや1×ペースの測定ではありません。HTTPS→loopbackのChrome/Firefox/Safari手動確認と人による承認は未実施です。','Source d1a2522 and Lab a744954 are READY on Vercel; /health/live and /health/ready returned HTTP 200 with true. Headless Chrome 157 from the production origin paired and completed MJ-BV01 at tick 4810, served 2; the run was archived. With 16× selected, the UI run took 78.4 seconds including network, UI and report overhead, not a CPU or 1× pacing benchmark. Manual Chrome/Firefox/Safari HTTPS-to-loopback checks and human acceptance have not run.')+'</article></div><div class="scope"><h3>'+tr('Cách nói chính xác khi demo','デモでの正確な説明','How to describe the demo accurately')+'</h3>'+p('“Đây là xArm 6 với kẹp G2 được mô phỏng bằng MuJoCo. Cốc được gắp bằng tiếp xúc trong mô hình; máy pha và AMR vẫn là mock. Tham số chưa hiệu chuẩn, nên kết quả chưa chứng minh tay máy, lực kẹp hay cốc thật.”','「これはMuJoCoでシミュレーションしたxArm 6とG2です。カップはモデル内の接触で把持しますが、コーヒーマシンとAMRはmockです。未校正のため、実機のアーム、把持力、カップの動作を証明するものではありません。」','“This is an xArm 6 with a G2 gripper simulated in MuJoCo. Cups are held by contact inside the model; the coffee machine and AMR remain mocks. Parameters are not calibrated, so this does not establish how a real arm, grip force or cup behaves.”')+p('Giá đỡ có phần được mô phỏng và phần minh họa; xem lưu ý trong menu Hiển thị. Replay thể hiện mẫu đã lưu, không nội suy thành bằng chứng vật lý mới.','支持構造にはシミュレーション部分と説明用部分があり、表示メニューの注意を確認します。再生は保存サンプルの表示で、新たな物理的証拠を生成しません。','Supports include simulated and illustrative pieces; read the Display menu note. Replay shows saved samples and does not create new physical evidence.')+'</div><details><summary>'+tr('Định danh và nguồn tham chiếu','識別情報と参照','Identity and references')+'</summary><div class="details-body"><dl class="identities"><div><dt>Source / runtime pin</dt><dd><code>'+FACTS['runtimeSourceCommit']+'</code></dd></div><div><dt>Lab · record commit</dt><dd><code>'+FACTS['labCommit']+'</code></dd></div><div><dt>Lab · production READY</dt><dd><code>'+FACTS['productionLabCommit']+'</code></dd></div><div><dt>Source · verified production</dt><dd><code>'+FACTS['productionSourceCommit']+'</code></dd></div><div><dt>Cloud Run revision</dt><dd><code>'+FACTS['cloud']['revision']+'</code></dd></div></dl><ul class="references"><li><a href="../docs/superpowers/specs/2026-11-12-realistic-arm-web-ui-design.md">R2a · '+tr('đặc tả','仕様','specification')+'</a></li><li><a href="../docs/implementation/evidence/sim-extension/r2a-candidate-02/README.md">R2a candidate-02 · '+tr('bản ghi cục bộ','ローカル記録','local qualification')+'</a></li><li><a href="../docs/implementation/evidence/cloud-run/mekoniq-2026-11-14/README.md">Cloud Run · CL01</a></li><li><a href="../docs/implementation/evidence/production/r2a-2026-11-14/browser-smoke.json">Production · Chrome smoke</a></li><li><a href="../docs/operations/lab-runtime-cloud-run.md">Cloud Run · '+tr('vận hành và chi phí','運用と費用','operations and cost')+'</a></li></ul>'+p('Liên kết source cần giữ cấu trúc repository. Nếu gửi riêng HTML, toàn bộ nội dung và ảnh vẫn đọc được offline.','sourceへのリンクにはrepository構造が必要です。HTML単体でも内容と画像はofflineで読めます。','Source links require the repository layout. The standalone HTML still contains all text and images for offline reading.')+'</div></details></section>'

cloud_gate_note = p('G-CLOUD1 = tested qua guard bổ sung cloud-run, gắn với đúng SHA-256 của bản ghi R2a. JSON R2a gốc vẫn giữ blocked_external theo định dạng cũ; bản bổ sung không sửa dữ liệu gốc và không thay thế nghiệm thu bởi con người.','G-CLOUD1 = testedはR2a記録の正確なSHA-256に紐づく追加guard cloud-runによるものです。元のR2a JSONは旧形式のblocked_externalを保持します。追加証跡は元データを変更せず、人による承認を代替しません。','G-CLOUD1 = tested through the supplemental cloud-run guard, bound to the exact R2a record SHA-256. The original R2a JSON retains its legacy blocked_external value; the supplement does not rewrite that record or replace human acceptance.','note')
proof = proof.replace('<div class="scope">', cloud_gate_note+'<div class="scope">', 1)

issues=[
 (('MUJOCO_CAPACITY: chỗ chạy đang được giữ','MUJOCO_CAPACITY: 実行枠を使用中','MUJOCO_CAPACITY: the worker slot is occupied'),('Cloud có một chỗ chạy MuJoCo. Sau khi xem báo cáo, thoát replay và bấm “Chạy lại cùng đầu vào” trong tab đang giữ run: Lab lưu báo cáo, archive run cũ rồi mới tạo run mới. “Ngắt kết nối” không archive. Nếu đã mất tab/phiên giữ run, nhờ người vận hành dọn run; đây là giới hạn dung lượng, không phải lỗi vật lý.','cloudのMuJoCo実行枠は1つです。レポート確認後に再生を終了し、runを保持するタブで「同じ入力で再実行」を押します。Labがレポート保存・旧runのarchive後に新規runを作成します。「切断」ではarchiveされません。タブ/sessionを失った場合は運用担当者にrunの解放を依頼します。物理エラーではなく枠の制限です。','Cloud has one MuJoCo worker slot. After reviewing the report, exit replay and use Run again with same inputs in the tab that owns the run: Lab saves the report and archives the previous run before creating the next one. Disconnect does not archive. If that tab/session is lost, ask the operator to clear the run. This is a capacity limit, not a physics failure.')),
 (('“Khác phiên bản” / RUNTIME_PIN_MISMATCH','「バージョン違い」/ RUNTIME_PIN_MISMATCH','“Other version” / RUNTIME_PIN_MISMATCH'),('So “Lab ghim” với “Runtime chạy”. Với cloud hiện tại, cả hai phải là 4f893ac. Dùng build/runtime tương ứng; không đổi lock tùy tiện hoặc bỏ kiểm tra.','「Labの固定」と「ランタイムの版」を比較。現在のcloudでは両方4f893acが必要です。対応するbuild/runtimeを使い、lockの書換えや検査回避はしません。','Compare Lab pinned to and Runtime runs. Both must be 4f893ac for this cloud runtime. Use the matching build/runtime; do not arbitrarily change the lock or bypass the check.')),
 (('Không thấy runtime','Runtimeが見つからない','Runtime is not reachable'),('Local: giữ launcher chạy và mở 127.0.0.1:4175. Web: chọn Địa chỉ khác và dùng URL HTTPS chuẩn. Nếu API trả HOST_FORBIDDEN, kiểm tra chính xác host; nếu lỗi origin, dùng đúng origin được phép.','ローカルではランチャーを起動したまま127.0.0.1:4175を開きます。Webでは別のアドレスと正規HTTPS URLを使います。HOST_FORBIDDENはhost、originエラーは許可オリジンを確認します。','Local: leave the launcher running and open 127.0.0.1:4175. Web: choose Another address and use the canonical HTTPS URL. For HOST_FORBIDDEN, check the exact host; for origin failures, use the allowed origin.')),
 (('Mã sai hoặc thử quá nhiều lần','コード不正・試行回数超過','Invalid code or too many attempts'),('Local dùng mã một lần mới trong terminal; cloud dùng khóa truy cập do người vận hành cấp. PAIRING_RATE_LIMITED: chờ một phút rồi thử lại, không lặp gửi mã liên tục.','ローカルはターミナルの新しいワンタイムコード、cloudは運用担当者のアクセスキーを使用。PAIRING_RATE_LIMITEDでは1分待ち、連続送信しません。','Local uses the fresh one-time terminal code; cloud uses the operator-provided access key. For PAIRING_RATE_LIMITED, wait a minute before trying again rather than repeatedly submitting codes.')),
 (('Preset bị vô hiệu hóa','プリセットが無効','A preset is disabled'),('Đọc mã lý do “Runtime này không chạy được”. Image cloud không có IR-SIM/Webots. Chuyển về đúng launcher local cho backend đó; không coi fallback mock là bằng chứng engine.','「このランタイムでは実行不可」の理由コードを読みます。cloud imageにはIR-SIM/Webotsがありません。対応するローカルランチャーを使い、mock代替をエンジン証拠と見なしません。','Read the “Not runnable on this runtime” reason. The cloud image has no IR-SIM/Webots. Use the matching local launcher; do not treat a mock fallback as engine evidence.')),
 (('Trình duyệt chặn loopback','ブラウザがloopbackをブロック','The browser blocks loopback access'),('Theo checklist LOOPBACK_BLOCKED của UI: runtime phải chạy, origin phải được phép và trình duyệt phải cấp quyền mạng cục bộ. Đường demo đơn giản hơn là UI local + runtime local; kiểm tay đa trình duyệt chưa được ghi nhận.','UIのLOOPBACK_BLOCKEDチェックに従い、runtime起動、origin許可、ブラウザのローカルネットワーク権限を確認します。簡単な経路はローカルUI＋ローカルruntimeです。複数ブラウザの手動検証は未記録です。','Follow the UI’s LOOPBACK_BLOCKED checklist: running runtime, allowed origin and local-network browser permission. The simpler demo route is local UI plus local runtime; cross-browser manual checks have not been recorded.')),
 (('Không có mesh hoặc WebGL','meshまたはWebGLが使えない','Meshes or WebGL are unavailable'),('Đọc lưu ý về hình thay thế, hoặc chuyển 2D. Đây là suy giảm hiển thị; kiểm báo cáo và trạng thái run riêng, không tự diễn giải thành engine thành công hay thất bại.','代替形状の注意を読むか2Dへ切り替えます。表示の劣化なので、レポートとrun状態を別途確認し、エンジンの成功/失敗と混同しません。','Read the fallback-geometry note or switch to 2D. This is a rendering limitation; check the report and run state separately instead of inferring engine success or failure.')),
 (('Run đã mất sau khi đóng tab / thay instance','タブを閉じた後・instance変更後にrunが消えた','The run is lost after closing the tab or replacing an instance'),('Cloud giữ run/session trong bộ nhớ. Khi instance dừng hoặc bị thay, có thể cần ghép nối và tạo run mới. Xuất/lưu báo cáo trước khi kết thúc demo.','cloudはrun/sessionをメモリに保持します。instance停止・置換時は再ペアリングと新規runが必要な場合があります。デモ終了前にレポートを出力/保存してください。','Cloud stores runs and sessions in memory. If an instance stops or is replaced, you may need to pair again and create a new run. Export/save the report before ending the demo.')),
]
help_='<section id="help" class="section">'+title('06','Nếu buổi demo bị ngắt','デモが止まったとき','If the demo is interrupted',('Giữ mã lỗi và xử lý đúng tầng: địa chỉ, phiên, phiên bản, backend hoặc hiển thị.','エラーコードを保持し、アドレス、session、version、backend、表示の層を切り分けます。','Keep the error code and resolve the right layer: address, session, version, backend or rendering.'))+'<div class="faq">'+''.join(details(h,p(*b)) for h,b in issues)+'</div></section>'
footer='<footer>'+p('Tài liệu hướng dẫn độc lập. Nút trong HTML chỉ điều hướng, sao chép hoặc phóng ảnh; không chạy mô phỏng, triển khai hay gửi lệnh robot.','この独立ガイドのボタンは移動、コピー、画像拡大のみ。シミュレーション、デプロイ、ロボット指令は実行しません。','This standalone guide only navigates, copies text and enlarges images. It does not run a simulation, deploy anything or send robot commands.')+'<a href="#overview">'+tr('Về đầu trang ↑','先頭へ ↑','Back to top ↑')+'</a></footer>'
dialog='<dialog id="lightbox" aria-labelledby="lightbox-title"><div class="lightbox-top"><h2 id="lightbox-title">'+tr('Ảnh từ kiểm thử local','ローカルテスト画像','Local test capture')+'</h2><button type="button" id="close-lightbox">'+tr('Đóng','閉じる','Close')+'</button></div><img id="lightbox-image" alt=""><div id="lightbox-caption"></div></dialog><div id="toast" role="status" aria-live="polite"></div>'
css=(HERE/'style.css').read_text();js=(HERE/'app.js').read_text()
body=sidebar+'<main>'+toolbar+hero+state+connect+demo+features+capabilities+proof+help_+footer+'</main>'+dialog
result='<!doctype html><html lang="vi" data-lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>MEKONIQ R2a · Demo Web & Local</title><style>'+css+'</style></head><body><a class="skip-link" href="#connect">'+tr('Đến hướng dẫn demo','デモ手順へ','Skip to demo instructions')+'</a><noscript><p class="no-script">'+tr('JavaScript đang tắt: toàn bộ hướng dẫn vẫn đọc được; nút đổi ngôn ngữ, sao chép và phóng ảnh không hoạt động.','JavaScriptが無効です。全手順は読めますが、言語切替・コピー・画像拡大は動作しません。','JavaScript is disabled: all instructions remain readable; language switching, copy and image zoom are unavailable.')+'</p></noscript>'+body+'<script>'+js+'</script></body></html>'
OUT.write_text(result)
manifest={'schemaVersion':1,'artifact':OUT.name,'sha256':hashlib.sha256(OUT.read_bytes()).hexdigest(),'bytes':OUT.stat().st_size,'inputs':{name:hashlib.sha256((HERE/name).read_bytes()).hexdigest() for name in ['build.py','style.css','app.js','facts.json']},'translationTriples':len(TRANSLATIONS),'shellCommands':COMMANDS,'images':FACTS['images'],'runtimeSourceCommit':FACTS['runtimeSourceCommit'],'labCommit':FACTS['labCommit']}
(HERE/'build-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
print(f'Built {OUT.name}: {manifest["bytes"]} bytes, {len(TRANSLATIONS)} translation triples, {len(COMMANDS)} shell blocks')
